        /// <summary>取某格（按原版瓦片键）的 Cel；<see cref="None"/> = 原版不画这格。</summary>
        public static short Cel(int areaId, bool objectLayer, string tileKey)
        {
            var tbl = objectLayer ? _object : _ground;
            if (tileKey == null || areaId < 0 || areaId >= tbl.Length) return None;
            short cel;
            return tbl[areaId].TryGetValue(tileKey, out cel) ? cel : None;
        }

        private static Dictionary<string, short> Build(string[] flat)
        {
            var d = new Dictionary<string, short>(flat.Length / 2);
            for (var i = 0; i + 1 < flat.Length; i += 2) d[flat[i]] = short.Parse(flat[i + 1]);
            return d;
        }

        private static byte[] Decode(string b64) => System.Convert.FromBase64String(b64);
    }
